DELETE rp
FROM platform_role_permission rp
JOIN platform_rbac_button b ON b.id = rp.button_id
WHERE b.system_code = 'alipay' AND b.page_code = 'config';
UPDATE platform_rbac_api_rule ar
JOIN platform_rbac_button b ON b.id = ar.button_id
SET ar.enabled = 0,
    ar.updated_at = NOW()
WHERE b.system_code = 'alipay' AND b.page_code = 'config';
UPDATE platform_rbac_button
SET enabled = 0,
    updated_at = NOW()
WHERE system_code = 'alipay' AND page_code = 'config';
UPDATE platform_rbac_page
SET enabled = 0,
    updated_at = NOW()
WHERE system_code = 'alipay' AND page_code = 'config';
UPDATE platform_rbac_system SET system_name='租赁管理中台' WHERE system_code='platform';
UPDATE platform_rbac_system SET system_name='租赁业务管理' WHERE system_code='alipay';
SELECT r.id,b.id FROM platform_role r CROSS JOIN platform_rbac_button b
WHERE r.role_code='super_admin' AND b.enabled=1;

-- Legacy numeric grant IDs can refer to buttons retired by the menu deltas above.
-- A fresh public installation must not retain dangling grants or API rules.
DELETE p FROM platform_role_permission p
LEFT JOIN platform_role r ON r.id=p.role_id
LEFT JOIN platform_rbac_button b ON b.id=p.button_id
WHERE r.id IS NULL OR b.id IS NULL;
DELETE a FROM platform_rbac_api_rule a
LEFT JOIN platform_rbac_button b ON b.id=a.button_id
WHERE b.id IS NULL;

-- Public functional guide: a read-only frontend page, with no business write API.
